def check_visibility(x1, y1, x2, y2, x3, y3, x4, y4, x5, y5, x6, y6):
    # Check if the white sheet is completely covered by either black sheet
    def is_completely_covered(x1, y1, x2, y2, x3, y3, x4, y4):
        return x3 <= x1 and x2 <= x4 and y3 <= y1 and y2 <= y4

    if is_completely_covered(x1, y1, x2, y2, x3, y3, x4, y4) or is_completely_covered(x1, y1, x2, y2, x5, y5, x6, y6):
        return "NO"

    # Check if any part of the white sheet can be seen
    def is_visible(x1, y1, x2, y2, x3, y3, x4, y4):
        return not (x3 >= x2 or x4 <= x1 or y3 >= y2 or y4 <= y1)

    if is_visible(x1, y1, x2, y2, x3, y3, x4, y4) or is_visible(x1, y1, x2, y2, x5, y5, x6, y6):
